#!/bin/sh
# Renders the icon sources in this directory to the files electron-builder and
# the app use.
#
# Sources (generated by docs/design/icon-options-v2/build6.py --final):
#   icon.icon        Icon Composer master. electron-builder compiles it to
#                    Assets.car for macOS 26 (Liquid Glass, dark, tinted).
#   icon-small.icon  Heavier variant for the 16 and 32 px icns slots.
#   trayTemplate.svg Menu-bar template image.
#
# Outputs: icon.png (1024), icon-dev.png (1024, the Dock and window icon of
# unpackaged runs), icon.icns (older macOS and the icns fallback),
# trayTemplate.png and trayTemplate@2x.png.
#
# `render-icons.sh dev` only rebuilds icon-dev.png from the committed icon.png;
# that step needs python3 with Pillow and nothing else.
#
# Needs Xcode 26 (Icon Composer's ictool), macOS sips and iconutil, python3
# with Pillow (for the grid drop shadow), and rsvg-convert (brew install librsvg).
set -eu
cd "$(dirname "$0")"

# The dev icon recolours icon.png: amber body, white envelope, and a dark band
# reading DEV across the bottom, so a dev run never looks like the installed app.
render_dev() { # icon.png icon-dev.png
  python3 - "$1" "$2" <<'PY'
import sys
from PIL import Image, ImageChops, ImageDraw, ImageFont

src = Image.open(sys.argv[1]).convert("RGBA")
r, g, b, a = src.split()
lum = Image.merge("RGB", (r, g, b)).convert("L")
# Body pixels are near-black, the envelope frame is white. Map luminance onto
# an amber ramp so the body turns amber and the frame stays white, keeping
# the original shading.
lo, hi = (226, 104, 0), (255, 255, 255)
ramp = [tuple(round(lo[c] + (hi[c] - lo[c]) * max(0, v - 30) / 225) for c in range(3)) for v in range(256)]
tinted = Image.merge("RGB", [lum.point([ramp[v][c] for v in range(256)]) for c in range(3)])
# The drop shadow is black at alpha <= 90; leave it alone. Body pixels are opaque.
weight = a.point(lambda v: 0 if v <= 90 else min(255, (v - 90) * 255 // 150))
out = Image.composite(Image.merge("RGBA", (*tinted.split(), a)), src, weight)

# Dark band across the bottom of the body, clipped to the body's outline.
band = Image.new("L", out.size, 0)
ImageDraw.Draw(band).rectangle((0, 760, 1024, 1024), fill=255)
band = ImageChops.multiply(band, weight)
out.paste((24, 24, 27, 255), mask=band)

font = None
for path, index in (("/System/Library/Fonts/SFNS.ttf", 0), ("/System/Library/Fonts/Helvetica.ttc", 1)):
    try:
        font = ImageFont.truetype(path, 132, index=index)
        try:
            font.set_variation_by_name(b"Heavy")
        except Exception:
            pass
        break
    except OSError:
        continue
draw = ImageDraw.Draw(out)
draw.text((512, 842), "DEV", font=font, fill=(255, 255, 255, 255), anchor="mm")
out.save(sys.argv[2])
PY
}

if [ "${1-}" = dev ]; then
  render_dev icon.png icon-dev.png
  exit 0
fi

ictool="/Applications/Xcode.app/Contents/Applications/Icon Composer.app/Contents/Executables/ictool"
[ -x "$ictool" ] || ictool="/Applications/Icon Composer.app/Contents/Executables/ictool"

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

# ictool renders the full-bleed body. Place it on the macOS grid (824 body at
# 100,100 on a 1024 canvas) with the standard soft drop shadow.
render() { # source.icon output.png
  "$ictool" "$1" --export-image --output-file "$tmp/raw.png" --platform macOS \
    --rendition Default --width 1024 --height 1024 --scale 1 >/dev/null
  python3 - "$tmp/raw.png" "$2" <<'PY'
import sys
from PIL import Image, ImageFilter
body = Image.open(sys.argv[1]).convert("RGBA").resize((824, 824), Image.LANCZOS)
canvas = Image.new("RGBA", (1024, 1024), (0, 0, 0, 0))
shadow = Image.new("RGBA", (1024, 1024), (0, 0, 0, 0))
sh = Image.new("RGBA", (824, 824), (0, 0, 0, 0))
sh.putalpha(body.split()[3].point(lambda a: a * 90 // 255))
shadow.alpha_composite(sh, (100, 112))
canvas.alpha_composite(shadow.filter(ImageFilter.GaussianBlur(14)))
canvas.alpha_composite(body, (100, 100))
canvas.save(sys.argv[2])
PY
}

render icon.icon icon.png
render_dev icon.png icon-dev.png
render icon-small.icon "$tmp/small.png"

iconset="$tmp/icon.iconset"
mkdir -p "$iconset"
for size in 16 32 128 256 512; do
  double=$((size * 2))
  # 16 and 32 px slots use the small-size variant; everything larger uses the master.
  src=icon.png
  [ "$size" -le 32 ] && src="$tmp/small.png"
  sips -z "$size" "$size" "$src" --out "$iconset/icon_${size}x${size}.png" >/dev/null
  src2=icon.png
  [ "$double" -le 32 ] && src2="$tmp/small.png"
  sips -z "$double" "$double" "$src2" --out "$iconset/icon_${size}x${size}@2x.png" >/dev/null
done
iconutil -c icns "$iconset" -o icon.icns

rsvg-convert -w 22 -h 22 trayTemplate.svg -o trayTemplate.png
rsvg-convert -w 44 -h 44 trayTemplate.svg -o trayTemplate@2x.png
